    String formattedMessage = null;

    try {
        // Get the conversion pattern from the LoggingEvent
        String conversionPattern = event.getConversionPattern();

        // Check if the conversion pattern is null or empty
        if (conversionPattern != null && !conversionPattern.isEmpty()) {
            // Create a Matcher object to match the conversion pattern
            Matcher matcher = CONVERSION_PATTERN_REGEX.matcher(conversionPattern);

            // Iterate over the pattern and replace the formatting placeholders
            while (matcher.find()) {
                String conversionKey = matcher.group(1);
                String converter = matcher.group(2);
                String formattingOptions = matcher.group(3);

                // Get the formatted value for the conversion key
                String formattedValue = getFormattedValue(event, conversionKey, converter, formattingOptions);

                // Replace the formatting placeholder with the formatted value
                conversionPattern = conversionPattern.replace(matcher.group(), formattedValue);
            }
        } else {
            // If the conversion pattern is null or empty, return the original message
            formattedMessage = event.getFormattedMessage();
        }
    } catch (Exception e) {
        // If there is an error during formatting, return the original message
        formattedMessage = event.getFormattedMessage();
    }

    return formattedMessage;
}

