private String getFormattedValue(LoggingEvent event, String conversionKey, String converter, String formattingOptions) {
    // Get the converter class
    Class<? extends Converter> converterClass = null;
    try {
        converterClass = Class.forName(converter).asSubclass(Converter.class);
    } catch (ClassNotFoundException e) {
        throw new IllegalStateException("Converter class not found: " + converter, e);
    }

