    Converter converterInstance = converterClass.newInstance();

    // Initialize the converter instance with the formatting options
    converterInstance.setOptions(formattingOptions);

    // Get the formatted value for the conversion key
    Object formattedValue = converterInstance.convert(event.getMDCPropertyMap().get(conversionKey));

    return String.valueOf(formattedValue);
}

