public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("output stream cannot be null");
    }
    if (message == null) {
        throw new NullPointerException("message cannot be null");
    }
    if (schema == null) {
        throw new NullPointerException("schema cannot be null");
    }
    if (buffer == null) {
        throw new NullPointerException("linked buffer cannot be null");
    }
    int size = ProtobufMessage.computeSerializedSizeDelimited(message, schema, buffer);
    if (size == 0) {
        return 0;
    }
    // Serialize the message and put it in a ByteBuffer
    ByteBuffer byteBuffer = ByteBuffer.allocate(size);
    try {
        ProtobufMessage.writeDelimitedTo(message, schema, byteBuffer, buffer);
        byte[] bytes = byteBuffer.array();
        out.write(bytes);
        return size;
    } finally {
        // Release the buffer
        byteBuffer.clear();
    }
}
