    if (path.isEmpty()) {
        // if empty, return the relative path as is
        return relativePath;
    }
    // split the path and the relative path into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // iterate over the relative path components and adjust the path accordingly
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            // handle the ".." case by removing the last component from the path
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
        } else if (!component.equals(".") && !component.isEmpty()) {
            // handle normal components by adding them to the path
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            pathComponents[pathComponents.length - 1] = component;
        }
    }

    // join the path components back into a single string
    return String.join("/", pathComponents);
}
