private String buildContentRange() {
    // Step 1: Validate inputs
    if (this.totalRecords == null || this.recordOffset == null || this.pageSize == null) {
        throw new IllegalArgumentException("Total records, record offset, and page size must be provided.");
    }

    // Step 2: Calculate the content range
    int firstRecord = this.recordOffset.intValue() + 1;
    int lastRecord = this.recordOffset.intValue() + this.pageSize.intValue();
    int totalRecords = this.totalRecords.intValue();
    String contentRange = "Content-Range: " + firstRecord + "-" + lastRecord + "/" + totalRecords;

    // Step 3: Handle invalid inputs
    if (firstRecord < 1 || lastRecord < 1) {
        throw new IllegalArgumentException("First record and last record must be greater than or equal to 1.");
    }
    if (lastRecord > totalRecords) {
        throw new IllegalArgumentException("Last record must be less than or equal to total records.");
    }

    return contentRange;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
   List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
   try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
       String line;
       while ((line = reader.readLine()) != null) {
           String[] parts = line.split(" ");
           ThreadSnapshot threadSnapshot = new ThreadSnapshot(
               Long.parseLong(parts[0]),
               Long.parseLong(parts[1]),
               Integer.parseInt(parts[2])
           );
           for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
               if (threadSnapshot.getTimestamp() >= timeRange.getStart() && threadSnapshot.getTimestamp() <= timeRange.getEnd()) {
                   threadSnapshots.add(threadSnapshot);
                   break;
               }
           }
       }
   } catch (IOException e) {
       e.printStackTrace();
   }
   return threadSnapshots;
}
